mapper.select:
SELECT * FROM ( SELECT T.*, ROWNUM rn FROM (
SELECT b.b_num, b.u_member_id, b.b_title, b.b_contents, b.b_category, b.b_dateposted, b.b_updateDate, b.b_views, b.b_recommend, b.b_image, NVL((SELECT COUNT(*) FROM comment_tbl c WHERE c.b_num = b.b_num), 0) AS b_comments, u.u_nickname FROM board_tbl b JOIN user_tbl u ON u.u_member_id = b.u_member_id WHERE 1=1
AND b.b_category = #{category}
AND b.b_dateposted >= TO_DATE(#{from}, 'YYYY-MM-DD')
AND b.b_dateposted < TO_DATE(#{to}, 'YYYY-MM-DD') + 1
AND ( b.b_title LIKE '%'||#{q}||'%' OR DBMS_LOB.INSTR(b.b_contents, #{q}) > 0 OR u.u_nickname LIKE '%'||#{q}||'%' )
ORDER BY b.b_dateposted DESC, b.b_num DESC
) T ) WHERE rn BETWEEN #{startRow} AND #{endRow}

