SELECT * FROM ( SELECT t.*, ROWNUM rn FROM ( SELECT p.pd_id, p.pd_name, p.pd_description, p.pd_price, p.pd_stock, p.pd_pet_category, p.pd_category, p.pd_subcategory, p.pd_created, p.pd_updated, p.pd_brand, p.pd_image_url, p.pd_shipping_fee, p.pd_discount_rate, /* 한글 상태 → ON/OFF/WAIT 로 정규화해서 DTO의 pd_status에 매핑 */ CASE p.pd_status WHEN '판매중' THEN 'ON' WHEN '재입고대기' THEN 'WAIT' WHEN '품절' THEN 'OFF' ELSE 'OFF' END AS pd_status, p.pd_option FROM product_tbl p WHERE 1=1
AND p.pd_status =
'판매중' '품절' '재입고대기'
AND p.pd_subcategory BETWEEN #{catFrom} AND #{catTo}
AND (p.pd_name LIKE '%' || #{q} || '%' OR p.pd_brand LIKE '%' || #{q} || '%')
ORDER BY p.pd_id DESC ) t ) WHERE rn BETWEEN #{start} AND #{end}

